<?php
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/sms.php';method('POST');rate('sms_total',20,3600);challenge_check();$tel=sms_tel();$c=sms_config();$action=text_input('action',20);$types=['register'=>0,'lostpw'=>1,'binding'=>2,'Unbundling'=>3,'login'=>4];if(!isset($types[$action]))respond(null,422,'短信场景无效');$type=$types[$action];rate('sms:'.$action,5,3600);
$u=current_user();if(in_array($type,[2,3],true)&&!$u)respond(null,401,'请先登录');if($type===4&&empty($c['tel_reglogin']))respond(null,403,'论坛未开放短信登录');
$bound=one('SELECT uid,tel FROM '.table('comiis_sms_user').' WHERE tel=? ORDER BY dateline DESC LIMIT 1',[$tel]);if(in_array($type,[0,2],true)&&$bound)respond(null,422,'该手机号已绑定账号');if(in_array($type,[1,3],true)&&!$bound)respond(null,422,'手机号尚未绑定账号');if($type===3&&(int)$bound['uid']!==(int)$u['uid'])respond(null,403,'不能解绑其他用户的手机号');
foreach(explode("\n",$c['tel_limit']??'') as $telPrefix){$telPrefix=trim($telPrefix);if(strlen($telPrefix)>1&&strpos($tel,$telPrefix)===0)respond(null,403,'该手机号不可使用');}
$province=sms_province($tel,$c);
lock_user('sms_send',hash('sha256',$tel));$ip=$_SERVER['REMOTE_ADDR'];$latest=one('SELECT dateline FROM '.table('comiis_sms_temp').' WHERE tel=? OR ip=? ORDER BY dateline DESC LIMIT 1',[$tel,$ip]);$cooldown=max(60,(int)($c['code_time']??60));if($latest&&time()-(int)$latest['dateline']<$cooldown)respond(null,429,'请等待验证码发送间隔结束');
$limit=(int)($c['mfnum']??0);if($limit>0&&one('SELECT COUNT(*) n FROM '.table('comiis_sms_temp').' WHERE (tel=? OR ip=?) AND dateline>?',[$tel,$ip,time()-86400])['n']>=$limit)respond(null,429,'今日短信次数已达上限');
$len=max(4,min(8,(int)($c['code_len']??6)));$code=str_pad((string)random_int(0,(10**$len)-1),$len,'0',STR_PAD_LEFT);$ok=sms_provider($tel,$type,$code,$c);
exec_sql('INSERT INTO '.table('comiis_sms_log').' (uid,tel,ip,type,smscode,error,dateline,province,ua) VALUES (?,?,?,?,?,?,?,?,?)',[$u['uid']??0,$tel,$ip,$type,$code,$ok?'ok':'app_send_failed',time(),$province,substr($_SERVER['HTTP_USER_AGENT']??'APP',0,250)]);if(!$ok)respond(null,422,'短信发送失败，请稍后重试');
exec_sql('UPDATE '.table('comiis_sms_temp').' SET state=0 WHERE tel=? OR ip=?',[$tel,$ip]);exec_sql('INSERT INTO '.table('comiis_sms_temp').' (tel,ip,sid,code,uid,type,dateline,state,count) VALUES (?,?,?,?,?,?,?,1,0)',[$tel,$ip,substr(bin2hex(random_bytes(8)),0,6),$code,$u['uid']??0,$type,time()]);respond(['cooldown'=>$cooldown]);
